    for b in model.buffers():
        keep_ids.add(id(b)); keep_ptr.add(b.untyped_storage().data_ptr())
    for m_ in model.modules():
        for v in list(m_.__dict__.values()):
            if torch.is_tensor(v):
                keep_ids.add(id(v)); keep_ptr.add(v.untyped_storage().data_ptr())
    vic = []
    for o in gc.get_objects():
        try:
            if torch.is_tensor(o) and o.is_cuda and id(o) not in keep_ids:
                if o.untyped_storage().data_ptr() in keep_ptr:
                    continue
                s = o.numel() * o.element_size() / 2**30
                if s > 0.05:
                    vic.append((s, o))
        except Exception:
            pass
    vic.sort(key=lambda x: -x[0])
    for s, o in vic:
        try:
            o.untyped_storage().resize_(0)
        except Exception:
            pass
    del vic; gc.collect(); torch.cuda.empty_cache()
    reset()
    gc.collect(); torch.cuda.empty_cache()
    if lw.device.type != 'cuda':
        lw.data = lw.data.to('cuda')
    for p in model.parameters():
        if p.device.type != 'cuda':
            p.data = p.data.to('cuda')
