def nll_score():
    texts = [
        ("The quick brown fox", " jumps over the lazy dog."),
        ("The capital of France is", " Paris."),
        ("In a magical land of numbers, there lived", " a group of little number friends."),
        ("She opened the door and", " walked into the room."),
        ("The weather today is", " sunny and warm."),
        ("The first president of the United States was", " George Washington."),
    ]
    tot = 0.0; n = 0
    for p, c in texts:
        lp = logprob(p, c)
        if torch.is_tensor(lp):
            if lp.numel() > 1:
                tot += -float(lp.sum()); n += lp.numel()
            else:
                tot += -float(lp); n += 1
        else:
            tot += -float(lp); n += 1
    return tot / max(n, 1)

