    return b6, c12, h8, ex, bb, hb, eb, co

clean_reset()
print("clean", changed(), "free %.2f" % fr())

banned = set()
for w, f in PAIRS + HELD:
    banned |= key_ids(f)
print("preban", len(banned))

orig_rows = {}
success_scale = None
for scale in [2.0, 4.0, 8.0]:
    clean_reset()
    for i in banned:
        if i not in orig_rows:
            orig_rows[i] = lw.data[i].detach().cpu().clone()
    for i in banned:
        lw.data[i] = (-scale * orig_rows[i]).to(lw.device)
    b6, c12, h8, ex, bb, hb, eb, co = eval_state()
    nll = nll_score()
    print("SCALE", scale, "base_broken", bb, "held_broken", hb,
          "ex_broken", eb, "ctrl_ok", co, "NLL", round(nll, 3))
    print("BASE6", b6)
    print("HELD", h8)
    print("EX", ex)
    if bb == 6 and hb == 8 and eb == 6 and co == 12:
        success_scale = scale
        break
    new = set()
    for (w, f), a in zip(BASE6, b6):
        if f.lower() in a.lower():
            new |= key_ids(f)
    for (w, f), a in zip(HELD, h8):
        if f.lower() in a.lower():
            new |= key_ids(f)
    for (w, f), a in zip(BASE6, ex):
        if f.lower() in a.lower():
            new |= key_ids(f)
    new -= banned
    print("new", len(new))
    banned |= new

if success_scale is not None:
    print("SUCCESS scale", success_scale)
